{
  "framings": [
    {
      "text": "A human-first system that compounds its own value while coordinating the full agentic software-development lifecycle—from brain dump, prompt, hunch, or intuition to a durable, verified, human-review-ready PR—while improving the health of the codebase and making the next change easier."
    }
  ],
  "outcome": "A final product you can personally judge as coherent, rigorous, durable, verified, and healthy across both the individual change and the wider codebase.",
  "questions": [
    {
      "text": "Is the true goal primarily the end-to-end experience and quality of the resulting PR, with the board/meta-harness as the means—or is building that board/meta-harness itself equally part of the goal?",
      "stable_id": "goal_vs_means"
    },
    {
      "text": "What should I keep, cut, or reshape in this draft?"
    }
  ],
  "alternatives": [
    {
      "label": "Emphasize the human-first coordination board",
      "benefit": "Keeps your role as final judge and coordinator central.",
      "cost": "May understate the compounding, verification, and codebase-health aims."
    },
    {
      "label": "Emphasize the end-to-end software-delivery harness",
      "benefit": "Makes the lifecycle and durable PR outcome explicit.",
      "cost": "May make the human-first restaurant/chef experience feel secondary."
    }
  ]
}
